// Leave a list empty to allow everything
const FROM_CONTAINS = [];          // e.g. ['@client.com', 'stripe']
const SUBJECT_CONTAINS = [];       // e.g. ['order', 'booking']
const EXCLUDE = ['unsubscribe'];   // skip newsletters
const has = (s, list) => list.some(w => (s || '').toLowerCase().includes(w.toLowerCase()));
return $input.all().filter(({ json: e }) => {
  const from = e.from?.text || ''; const subj = e.subject || ''; const body = e.text || '';
  if (FROM_CONTAINS.length && !has(from, FROM_CONTAINS)) return false;
  if (SUBJECT_CONTAINS.length && !has(subj, SUBJECT_CONTAINS)) return false;
  return !has(`${from} ${subj} ${body}`, EXCLUDE);
}).map(({ json: e }) => ({ json: { from: e.from?.text || '?', subject: e.subject || '(no subject)', preview: (e.text || '').replace(/\s+/g, ' ').slice(0, 300) } }));
